// Fuente PT Sans (regular + negrita) incrustada en base64: react-pdf necesita
// una fuente con glifos cirílicos para el contenido en ruso (Helvetica, la
// fuente base de PDF, no tiene) y también cubre los caracteres extendidos
// del español (ñ, á, ¿, ¡) en el MISMO archivo. Se incrusta en vez de leerla
// del disco porque el empaquetado de Vercel para funciones serverless no
// siempre incluye archivos binarios referenciados solo por ruta de archivo.
export const PT_SANS_REGULAR_BASE64 = "";
export const PT_SANS_BOLD_BASE64 = "";
